WFJ.Data.add("quest", {
  [78088] = { "奇妙な遺物", "Althalaxx OrbをAshenvaleのMaestra's PostにいるDelgren the Purifierに届ける。", "<手にした謎めいたorbが、あなたを冷たい恐怖で満たす。心の中で声がかすかに響くのが聞こえるような気がする。低く喉にかかったその声を聞けば、話されている言葉が悪魔のものであることはよく分かる。\n\nパラディンであっても、この魔法はあなたの手に余る。このKalimdorで、この不吉な物の正体を見極める手助けをしてくれそうな、より位の高いパラディンを探すのだ。>", nil, nil, 0x54d84c8e, 0xf162540c, 0x00ddba1f, nil, nil, "...mm" },
  [78089] = { "Stormwindからの助言", "Althalaxx OrbをStormwindのKatherine the Pureに届ける。", "このorbには強大な闇がまとわりついている。その性質は明らかに悪魔のものだが、それ以上となると、目的を見極めるのは私の力では無理だ。\n\nこのorbを、Stormwind CathedralにいるKatherine the Pureと呼ばれる方のところへ持って行ってくれ。orbについて彼女に助言を求めるといい。", nil, nil, 0x5e36a76b, 0x3b4d2dbd, 0x789ee65c, nil, nil, "...mm" },
  [78090] = { "別の意見", "Stormwind内にあるウォーロックの聖域を見つけ、オーブのことで助言を求める。", "この宝珠をどう考えたものか分からないのです、{name}。どうやら……専門家の助けが必要になりそうです。\n\nStormwindを拠点に活動しているウォーロックの一派がいることは把握しています。表向きには、私たちはこの街にウォーロックがいることを認めていません。しかし裏では、悪魔の力に対処する際、彼らの知識が役に立つこともあるのです。\n\nこのウォーロックたちの代表者を探し出し、宝珠について意見を求めてください。", nil, nil, 0x87bb7435, 0x7c900333, 0x547fdd46, nil, nil, "...mm" },
  [78091] = { "給料分の働き", "Redridge MountainsのBlackrock SummonersからSummoner's Saltを14個集め、StormwindのUrsula Delineのもとへ戻る。", "宝珠を調べて分かったことを教えてやろう。だが、その前にまず私の頼みを聞いてもらう。\n\nBlackrock氏族のウォーロックたちは、召喚の儀式を強化するために特別に調合したsaltsを使っている。Redridgeにいるオークどもから、それをいくらか集めてこい。\n\n戻ってきたら、研究の結果を教えてやろう。", nil, nil, 0x7d78a823, 0x1de3212f, 0xd4dd5884, nil, nil, "...mm" },
  [78092] = { "破壊せねばならない", "Ashenvaleの悪魔からMotes of Mannorothを12個集める。それをOrb of Althalaxxと一緒にDemon Fall CanyonのSpear of Mannorothへ持っていく。", "この宝珠から伸びてくる意思の触手は、私のような熟練のウォーロックでさえ長くは耐えられないほど強い。認めたくはないが、{name}、この宝珠は破壊しなければならない。\n\n宝珠はほとんど傷つかないが、強大な悪魔の君主の武器なら通じるかもしれない。そのような刃がAshenvaleにあると聞いている。pit lordであるMannorothが倒された場所だ。\n\nそこで倒れた悪魔の精髄の粒を集め、その刃の上で宝珠を砕くのだ。", nil, nil, 0x725d212a, 0x5fdc36a4, 0x72f2a6fa, nil, nil, "...mm" },
  [78093] = { "Delgrenのもとへ戻る", "Orb ShardsをDelgrenに返す。", "<砕けた宝珠の残骸が足元に転がっている。Delgrenはあなたが成功したことを確かめたがるだろう。>", nil, nil, 0x63f744cd, 0x47cd34b6, 0xc8898e87, nil, nil, "...mm" },
  [78124] = { "Nar'thalas Almanac", nil, nil, nil, nil, 0x3a40adb9, nil, nil, nil, nil, ".mmmm" },
  [78127] = { "Dalaran要覧", nil, nil, "私たちのコレクションに加える品を、何か持ってきてくれたか？", "ありがとうございます、{name}。あなたの尽力で私たちの知識は広がります。\n\n図書館の役に立ちそうな魔法の書物をほかにも見つけたら、ぜひ私のところへ持ってきてください。", 0x3c34dd7c, nil, nil, 0x1400fbf0, 0xe184a784, ".mm.." },
