  [78261] = { "Horn of Xelthos", "Shadowfang Keepの中でThe Horn of Xelthosを見つけてください。それから、Pyrewood Villageの近くにあるCの隠し場所へそれを届けてください。この仕事は一人でやり遂げなければなりません。", "<箱の中にメモが入っている>\n\nこんにちは、{name}。\n\n私は、Shadowfang Keepのどこかにあると言われる、Horn of Xelthosという宝を求めている。\n\nあの砦の中に入り込むには、普通なら援護が必要だ。だが今回の仕事では、目立たないことが何より重要だ。\n\n一人で行かねばならない。\n\nStonetalon Mountainsに、Veenixという名の連絡役がいる。彼なら中庭の門を越える手助けをしてくれるはずだ。その先はお前次第だ。\n\n角笛をここへ戻してくれれば、その後すぐに報酬を送る。\n\n- C", nil, nil, 0x8ef63440, 0xa04dc89a, 0x3eb0aa8f, nil, nil, "...mm" },
  [78270] = { "ゴブリンのロックピック", "Shadowfang Keepの中でThe Horn of Xelthosを見つけ、Pyrewood Village近くのCの隠し場所に届けて下さい。", "<木箱の中に手紙が置かれている>\n\nまた会ったな、{name}。\n\nShadowfang Keepのどこかにある、The Horn of Xelthosという財宝が欲しい。\n\nあの砦に乗り込むなら、普通は援軍が要る。だがこの仕事では、目立たないことが何より重要だ。\n\n一人で行け。\n\nStonetalon Mountainsに、Veenixという名の協力者がいる。中庭の門を抜けるのを手伝ってくれるはずだ。あとはお前次第だ。\n\n角笛をここに持ち帰れば、報酬はすぐに送られる。\n\n- C", nil, nil, 0x6567783d, 0x8f719ff2, 0xe73ec883, nil, nil, "...mm" },
  [78307] = { "Horn of Xelthos", nil, nil, nil, nil, 0x8ef63440, nil, nil, nil, nil, ".mmmm" },
  [78676] = { "Eye of Bhossca", "Scarlet Monastery内でThe Eye of Bhosscaを見つける。それからPyrewood Village近くのCの受け渡し場所へ戻す。この仕事は一人でやり遂げなければならない。", "<箱の中にメモが入っている>\n\nまた会えて嬉しいよ、{name}。\n\n私が今欲しているのは、Eye of Bhosscaと呼ばれる遺物だ。情報筋によれば、その目はScarlet Monasteryのどこかにあるらしい。Shadowfang Keepのときと同じく、修道院には一人で潜入してもらう。\n\n入る前に変装を見つけておくといいだろう。動き回るのが少し楽になる。修道院の敷地で何か見つかるはずだ。\n\nその目をここへ持ち帰れば、前回と同じように報酬を届けよう。\n\n- C", nil, nil, 0xdb721cea, 0x84b09c9a, 0xdef0af60, nil, nil, "...mm" },
  [78699] = { "Eye of Bhossca", nil, nil, nil, nil, 0xdb721cea, nil, nil, nil, nil, ".mmmm" },
  [78823] = { "砂漠の空の恐怖", "Primitive DrawingをStranglethorn ValeのHemet Nesingwaryに届ける。", "このdrawingは粗く太い筆致で描かれており、大きな猛禽を表しているようだ。単純な構図だが、描き手がこの生き物を恐れ、畏敬していたことは明らかだ。大物の獲物に詳しい者なら、もっと詳しく教えてくれるだろう。", nil, nil, 0x095389a7, 0xee6d5c93, 0x946d35b2, nil, nil, "...mm" },
  [78830] = { "砂漠の空の恐怖", "BadlandsのGharrikからCrimson Trophy Quillを手に入れる。それからStranglethorn ValeのHemet Nesingwaryのもとへ戻る。", "この絵を見て、少し前に別の遠征で聞いた話を思い出したよ。Gharrikという大きな鳥が、頂点の捕食者としてBadlandsに君臨しているそうだ。\n\n最後に目撃されたのはCamp Caggの北東だ。巣はその近くのどこかにあるんじゃないか？\n\nおびき出すには生き餌が要る。捕まえるための檻を貸してやろう。Badlandsには小さな野生動物がほとんどいないから、餌はよそで探す必要がある。\n\nGharrikのquillなら立派な戦利品になる。きっとキャンプ中の話題になるぞ。", nil, nil, 0x095389a7, 0x538655d8, 0x1ada8d6b, nil, nil, "...mm" },
  [78916] = { "虚無の心臓", "Blackfathom PearlをDarnassusのDawnwatcher Selgormに届ける。", "恐るべき獣Aku'maiは息絶えた。膨れ上がった死骸の臓物と血肉の中に、生のVoidエネルギーに満ちた巨大な虹色の真珠が隠されている。", nil, nil, 0xc885df05, 0x864e71af, 0x0a93b80a, nil, nil, "...mm" },
  [78917] = { "虚無の心臓", "Blackfathom PearlをThunder BluffのBashana Runetotemに届ける。", "恐るべき獣Aku'maiは息絶えた。膨れ上がった死骸の臓物と血肉の中に、生のVoidエネルギーに満ちた巨大な虹色の真珠が隠されている。", nil, nil, 0xc885df05, 0x793b6e73, 0x0a93b80a, nil, nil, "...mm" },
